<?php try { $pdo = new PDO("mysql:host=localhost;dbname=urbanova_db;charset=utf8mb4","root","", [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]); $tables=["users","investors","projects","news"]; foreach($tables as $t){ $stmt=$pdo->query("SELECT COUNT(*) as c FROM $t"); $row=$stmt->fetch(PDO::FETCH_ASSOC); echo "$t: {$row["c"]}\n"; } echo "\nLast 5 users:\n"; $stmt=$pdo->query("SELECT id,email, name, first_name, last_name, role, status, created_at FROM users ORDER BY id DESC LIMIT 5"); foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $r){ print_r($r);} echo "\nLast 5 projects:\n"; $stmt=$pdo->query("SELECT id,title, status, validation_status, promoter, promoter_id, created_at FROM projects ORDER BY id DESC LIMIT 5"); foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $r){ print_r($r);} echo "\nLast 5 news:\n"; $stmt=$pdo->query("SELECT id,title,status,created_at FROM news ORDER BY id DESC LIMIT 5"); foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $r){ print_r($r);} } catch (PDOException $e) { echo $e->getMessage(); } ?>
